solution.js:
function hasNearbyRepeat(badges, k) {
  const last = new Map()
  for (let j = 0; j < badges.length; j++) {
    const id = badges[j]
    if (last.has(id) && j - last.get(id) <= k) return true
    last.set(id, j)
  }
  return false
}

